// Same-origin check: origin = scheme + host + port (path and query ignored)
function origin(u) {
  const x = new URL(u);
  return x.protocol + "//" + x.hostname + ":" + (x.port || (x.protocol === "https:" ? "443" : "80"));
}
function sameOrigin(a, b) {
  return origin(a) === origin(b);
}
const base = "https://app.com/home?x=1";
const tests = [
  "https://app.com/other",        // path differs only
  "http://app.com/home",          // scheme differs
  "https://api.app.com/home",     // subdomain differs
  "https://app.com:8443/home",    // port differs
  "https://app.com:443/x",        // default port written out
];
console.log("base:", base, "->", origin(base));
for (const t of tests) {
  console.log(t, "->", sameOrigin(base, t) ? "same-origin" : "cross-origin");
}

// Decide whether a fetch needs a CORS preflight (simplified rules)
const SAFE_HEADERS = ["accept", "accept-language", "content-language", "content-type"];
const SAFE_TYPES = ["application/x-www-form-urlencoded", "multipart/form-data", "text/plain"];

function needsPreflight(req) {
  if (!["GET", "HEAD", "POST"].includes(req.method)) return true;
  for (const name of Object.keys(req.headers)) {
    const h = name.toLowerCase();
    if (!SAFE_HEADERS.includes(h)) return true;      // custom or Authorization header
    if (h === "content-type" && !SAFE_TYPES.includes(req.headers[name])) return true;
  }
  return false;
}

const requests = [
  { method: "GET", headers: {} },
  { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" } },
  { method: "POST", headers: { "Content-Type": "application/json" } },
  { method: "GET", headers: { Authorization: "Bearer t" } },
  { method: "DELETE", headers: {} },
];
for (const r of requests) {
  const ct = r.headers["Content-Type"] || "-";
  console.log(r.method, "ct=" + ct, "auth=" + (r.headers.Authorization ? "yes" : "no"),
    "->", needsPreflight(r) ? "PREFLIGHT" : "simple");
}

// Escape untrusted text before putting it into HTML
function escapeHtml(s) {
  return s
    .replace(/&/g, "&amp;")   // must come first
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
const comment = '<img src=x onerror="alert(1)"> Tom & Jerry';
const unsafe = "<p>" + comment + "</p>";           // the browser would run onerror
const safe = "<p>" + escapeHtml(comment) + "</p>";  // shown as plain text
console.log("input :", comment);
console.log("unsafe:", unsafe);
console.log("safe  :", safe);
console.log("tag survives in unsafe:", unsafe.includes("<img"));
console.log("tag survives in safe  :", safe.includes("<img"));

// CSRF synchronizer token: server stores a secret per session, form must echo it back
const crypto = require("crypto");
const sessions = { s1: { csrf: "tok-abc123" } };   // fixed value so output is stable

function handleTransfer(req) {
  const sess = sessions[req.cookieSid];            // cookie is sent automatically by browser
  if (!sess) return "401 not logged in";
  const a = Buffer.from(sess.csrf), b = Buffer.from(req.body.csrf || "");
  // constant-time compare, lengths must match first
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return "403 bad CSRF token";
  return "200 transferred " + req.body.amount;
}

const legit = { cookieSid: "s1", body: { amount: 50, csrf: "tok-abc123" } };
const forged = { cookieSid: "s1", body: { amount: 5000 } };   // attacker page cannot know token
const wrong = { cookieSid: "s1", body: { amount: 5000, csrf: "guess" } };
console.log("legit :", handleTransfer(legit));
console.log("forged:", handleTransfer(forged));
console.log("wrong :", handleTransfer(wrong));

// CORS: reflecting any Origin vs a strict allowlist
const ALLOWED = new Set(["https://app.example.com", "https://admin.example.com"]);

function reflectAll(origin) {            // BAD: every site gets credentials access
  return { "Access-Control-Allow-Origin": origin, "Access-Control-Allow-Credentials": "true" };
}
function strict(origin) {                // GOOD: exact match on the whole origin
  if (!ALLOWED.has(origin)) return {};   // no CORS headers at all
  return { "Access-Control-Allow-Origin": origin, "Access-Control-Allow-Credentials": "true", Vary: "Origin" };
}
const origins = ["https://app.example.com", "https://evil.test", "https://app.example.com.evil.test", "null"];
for (const o of origins) {
  console.log("Origin:", o);
  console.log("  reflect:", JSON.stringify(reflectAll(o)));
  console.log("  strict :", JSON.stringify(strict(o)));
}
